-- Idempotent DISC kamus seed. Strings are copied from refs/disc.md.
-- Re-running updates section 5 patterns, section 6 traits, and section 4.5 statuses.
-- Pattern codes outside section 5 are marked inactive. Sub-trait and graph-meaning rows are marked inactive.

ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  jobs = EXCLUDED.jobs,
  is_active = EXCLUDED.is_active,
  updated_at = NOW();

UPDATE disc_patterns
SET is_active = FALSE, updated_at = NOW()
WHERE code NOT IN ('C', 'D', 'D-I', 'D-I-S', 'D-S', 'D-C', 'D-I-C', 'D-S-I', 'I', 'I-S', 'I-C', 'I-S-C', 'S', 'S-C', 'S-I', 'S-I-C', 'C-I', 'C-D-I', 'C-D-S', 'C-S-D');

UPDATE disc_subtraits
SET is_active = FALSE;

UPDATE disc_graph_meanings
SET is_active = FALSE;

ON CONFLICT (dim) DO UPDATE SET
  heading = EXCLUDED.heading,
  potret_diri = EXCLUDED.potret_diri,
  kelebihan = EXCLUDED.kelebihan,
  kekurangan = EXCLUDED.kekurangan,
  kecenderungan = EXCLUDED.kecenderungan,
  lingkungan_cocok = EXCLUDED.lingkungan_cocok,
  saran_perbaikan = EXCLUDED.saran_perbaikan,
  updated_at = NOW();

ON CONFLICT (status, graph_key) DO UPDATE SET
  arti = EXCLUDED.arti,
  context = EXCLUDED.context,
  updated_at = NOW();
